    }
}

public static class Solution
{
    public static string RemoveDuplicateCharacters(string s)
    {
        HashSet<char> set = new HashSet<char>();
        foreach (char c in s)
        {
            if (!set.Contains(c))
            {
                set.Add(c);
            }
        }
        return set.ToString();
    }
}

public static class Solution
{
    public static string TruncateWithEllipsis(string s, int maxLength)
    {
        if (maxLength <= 0) return "";
        if (maxLength >= 3) return $"{s.Substring(0, maxLength - 3)}...";
        return maxLength == 1 ? "." : ".";
    }
}

