public record Person(string Name, int Age);

public static class Solution
{
    public static List<string> GetAdultNamesSorted(List<Person> people)
    {
        return people
            .Where(p => p.Age >= 18)
            .OrderBy(p => p.Name)
            .Select(p => p.Name)
            .ToList();
    }
}

public record Product(string Category, decimal Price);

public static class Solution
{
    public static Dictionary<string, decimal> GetTotalPriceByCategory(List<Product> products)
    {
        return products
            .GroupBy(p => p.Category)
            .Select(g => new Dictionary<string, decimal>
            {
                [g.Key] = g.Sum(p => p.Price)
            })
            .ToDictionary(g => g.Key, g => g.Value);
    }
}

