public record Employee(string Name, decimal Salary, string Department);

public static class Solution
{
    public static List<string> HighestPaidNamesByDepartment(List<Employee> employees)
    {
        return employees
            .OrderBy(e => e.Name)
            .ThenByDescending(e => e.Salary)
            .ThenBy(e => e.Department)
            .Select(e => e.Name)
            .GroupBy(e => e.Department)
            .Select(g => g.OrderByDescending(e => e.Salary).Select(e => e.Name).First())
            .ToArray();
    }
}

