public record NumberPartition(List<int> Evens, List<int> Odds);

public static class Solution
{
    public static NumberPartition PartitionNumbers(List<int> numbers)
    {
        var evens = numbers.Where(n => n % 2 == 0).ToArray();
        var odds = numbers.Where(n => n % 2 != 0).ToArray();
        return new NumberPartition(evens, odds);
    }
}

public static class Solution
{
    public static int SumEvenSquares(List<int> nums)
    {
        int sum = 0;
        foreach (int num in nums)
        {
            if (num % 2 == 0)
            {
                sum += num * num;
            }
        }
        return sum;
    }
}

public static class Solution
{
    public static double AveragePositive(List<double> nums)
    {
        if (nums.Count == 0) return 0.0;
        double sum = 0.0;
        foreach (double num in nums)
        {
            if (num > 0.0) sum += num;
        }
        return sum / nums.Count;
    }
}

