public static class Solution
{
    public static Dictionary<string, int> CountByParity(List<int> nums)
    {
        Dictionary<string, int> counts = new Dictionary<string, int>
        {
            ["Even"] = 0,
            ["Odd"] = 0
        };

        foreach (int num in nums)
        {
            if (num % 2 == 0)
            {
                counts["Even"]++;
            }
            else
            {
                counts["Odd"]++;
            }
        }

        return counts;
    }
}

