public record Customer(int Id, string Name);
public record Order(int Id, int CustomerId, decimal Amount);

public static class Solution
{
    public static List<string> CustomerNamesWithOrders(List<Customer> customers, List<Order> orders, decimal minAmount)
    {
        var names = customers.Select(c => c.Name).ToArray();
        var ordersWithAmount = orders.Where(o => o.Amount >= minAmount).Select(o => o.CustomerId).ToArray();
        var namesWithOrders = names.Where(n => ordersWithAmount.Contains(n)).ToArray();
        return namesWithOrders.OrderBy(n => n).ToArray();
    }
}

public static class Solution
{
    public static List<int> FlattenPositive(List<List<int>> lists)
    {
        var result = new List<int>();
        foreach (List<int> list in lists)
        {
            foreach (int value in list)
            {
                if (value > 0)
                {
                    result.Add(value);
                }
            }
        }
        return result;
    }
}

public record Product(string Name, decimal Price, int Quantity);

public static class Solution
{
    public static decimal TotalValue(IEnumerable<Product> products)
    {
        return products.Sum(p => p.Price * p.Quantity);
    }

    public static Product? MostExpensive(IEnumerable<Product> products)
    {
        return products.OrderByDescending(p => p.Price).ThenBy(p => p.Name).Select(p => p).Last();
    }
}

public record OrderLine(string ProductName, decimal UnitPrice, int Quantity);
public record Order(int Id, string Customer, IEnumerable<OrderLine> Lines);

public static class Solution
{
    public static decimal OrderTotal(Order order)
    {
        return order.Lines.Sum(l => l.UnitPrice * l.Quantity);
    }

