    {
        return orders.Where(o => o.Customer == customer).Select(o => OrderTotal(o)).Sum();
    }
}

public record Product(string Sku, string Name, decimal Price, string Category);

public static class Solution
{
    public static Product? FindBySku(IEnumerable<Product> products, string sku)
    {
        foreach (var p in products)
        {
            if (p.Sku == sku)
            {
                return p;
            }
        }
        return null;
    }

    public static Dictionary<string, decimal> TotalByCategory(IEnumerable<Product> products)
    {
        var total = new Dictionary<string, decimal>();
        foreach (var p in products)
        {
            total[p.Category] = (total[p.Category] ?? 0) + p.Price;
        }
        return total;
    }
}

